import{_ as e,o as a,c as r,ag as d}from"./chunks/framework.4s5LDCII.js";const b=JSON.parse('{"title":"成人肥胖食养指南（2024年版）","description":"国家卫健委《成人肥胖食养指南（2024年版）》可执行整理：科学减重的行动清单，每条出处可一键跳回原文对应页。","frontmatter":{"title":"成人肥胖食养指南（2024年版）","issuer":"国家卫生健康委办公厅","source_tier":"一级来源","version":"2024年版","published":"2024-02","source_url":"https://www.nhc.gov.cn/wjw/c100378/202402/afd5dda4bd6745fda10aad8d43a16369/files/1732845128308_77058.pdf","status":"现行","tags":["肥胖","减重","食养","饮食指导","行动清单"],"reviewed":false,"description":"国家卫健委《成人肥胖食养指南（2024年版）》可执行整理：科学减重的行动清单，每条出处可一键跳回原文对应页。"},"headers":[],"relativePath":"guides/obesity-2024.md","filePath":"guides/obesity-2024.md"}'),i={name:"guides/obesity-2024.md"};function o(s,t,h,g,l,n){return a(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="成人肥胖食养指南-2024年版" tabindex="-1">成人肥胖食养指南（2024年版） <a class="header-anchor" href="#成人肥胖食养指南-2024年版" aria-label="Permalink to &quot;成人肥胖食养指南（2024年版）&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">初稿待人工校验</p><p>本页由 AI 依据官方 PDF 原文整理，尚未逐条对照原文校验；校验通过前请以原文为准。</p></div><div class="danger custom-block"><p class="custom-block-title">使用须知</p><p>本页所有建议均<strong>整理自官方文件原文</strong>，每条&quot;出处&quot;均可点击直达原文对应页；标注【本站提示】的少数条目为中性工具提示，不代表医学建议。本站不构成诊疗建议，与医生的治疗方案冲突时，<strong>以医嘱为准</strong>。</p></div><blockquote><p><strong>原文出处</strong>：国家卫生健康委办公厅印发（<a href="https://www.nhc.gov.cn/wjw/c100378/202402/afd5dda4bd6745fda10aad8d43a16369/files/1732845128308_77058.pdf" target="_blank" rel="noreferrer">官方全文 PDF（卫健委直链）</a>）· 一级来源。下文&quot;出处&quot;链接指向本站镜像的<a href="https://yshuai.github.io/SageRelay/guides-pdf/obesity-2024.pdf" target="_blank" rel="noreferrer">官方原文 PDF</a>（政府公文，属公共领域）。</p></blockquote><h2 id="这份文件适合谁" tabindex="-1">这份文件适合谁 <a class="header-anchor" href="#这份文件适合谁" aria-label="Permalink to &quot;这份文件适合谁&quot;">​</a></h2><p>成人超重与肥胖人群，以及希望预防肥胖、管理体重的一般人群（<a href="https://yshuai.github.io/SageRelay/guides-pdf/obesity-2024.pdf#page=3" target="_blank" rel="noreferrer">原文·前言</a>）。</p><h2 id="速览卡-一屏看完" tabindex="-1">速览卡（一屏看完） <a class="header-anchor" href="#速览卡-一屏看完" aria-label="Permalink to &quot;速览卡（一屏看完）&quot;">​</a></h2><p>核心原则：<strong>控制总能量摄入 + 吃动平衡 + 纠正不良饮食行为 + 规律作息</strong>。（<a href="https://yshuai.github.io/SageRelay/guides-pdf/obesity-2024.pdf#page=6" target="_blank" rel="noreferrer">原文·三</a>）</p><table tabindex="0"><thead><tr><th>关键数字</th><th>数值</th><th>出处</th></tr></thead><tbody><tr><td>每日能量</td><td>平均降低 <strong>30%～50% 或 500～1000kcal</strong>；或男性 1200～1500kcal、女性 1000～1200kcal</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/obesity-2024.pdf#page=7" target="_blank" rel="noreferrer">三(一)</a></td></tr><tr><td>个体化能量</td><td>理想体重(kg)=身高(cm)−105，×能量系数 15～35kcal/kg（卧床 15、轻活动 20～25、中活动 30～35）</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/obesity-2024.pdf#page=7" target="_blank" rel="noreferrer">三(一)</a></td></tr><tr><td>食盐</td><td><strong>≤5g/日</strong></td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/obesity-2024.pdf#page=8" target="_blank" rel="noreferrer">三(二)</a></td></tr><tr><td>烹调油</td><td><strong>20～25g/日</strong></td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/obesity-2024.pdf#page=8" target="_blank" rel="noreferrer">三(二)</a></td></tr><tr><td>添加糖</td><td>最好 <strong>&lt;25g/日</strong></td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/obesity-2024.pdf#page=8" target="_blank" rel="noreferrer">三(二)</a></td></tr><tr><td>高能量食物</td><td>提供 <strong>400kcal/100g 以上</strong>能量的食物要少吃</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/obesity-2024.pdf#page=8" target="_blank" rel="noreferrer">三(二)</a></td></tr><tr><td>有氧运动</td><td><strong>每周 150～300 分钟</strong>中等强度，每周 5～7 天、至少隔天 1 次</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/obesity-2024.pdf#page=10" target="_blank" rel="noreferrer">三(四)</a></td></tr><tr><td>抗阻运动</td><td><strong>每周 2～3 天</strong>、隔天 1 次、每次 10～20 分钟；每周运动消耗 ≥2000kcal</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/obesity-2024.pdf#page=10" target="_blank" rel="noreferrer">三(四)</a></td></tr><tr><td>久坐</td><td>静坐/伏案<strong>每小时起身活动 3～5 分钟</strong></td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/obesity-2024.pdf#page=10" target="_blank" rel="noreferrer">三(四)</a></td></tr><tr><td>睡眠</td><td>每日 <strong>7 小时左右</strong>，按昼夜节律作息</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/obesity-2024.pdf#page=10" target="_blank" rel="noreferrer">三(四)</a></td></tr><tr><td>合理减重速度</td><td><strong>每月 2～4kg</strong>（健康减重 5%～10% 有显著获益）</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/obesity-2024.pdf#page=7" target="_blank" rel="noreferrer">三(一)</a></td></tr></tbody></table><h2 id="行动清单" tabindex="-1">行动清单 <a class="header-anchor" href="#行动清单" aria-label="Permalink to &quot;行动清单&quot;">​</a></h2><h3 id="🛒-买" tabindex="-1">🛒 买 <a class="header-anchor" href="#🛒-买" aria-label="Permalink to &quot;🛒 买&quot;">​</a></h3><table tabindex="0"><thead><tr><th>怎么做</th><th>出处</th></tr></thead><tbody><tr><td>采购时<strong>主动阅读营养标签</strong>，选脂肪、碳水/糖、钠含量低的食物</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/obesity-2024.pdf#page=8" target="_blank" rel="noreferrer">三(二)</a></td></tr><tr><td>少买油炸食品、加工肉制品、含糖烘焙糕点、蜜饯、糖果、冰淇淋及含糖饮料</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/obesity-2024.pdf#page=8" target="_blank" rel="noreferrer">三(二)</a></td></tr><tr><td>多买全谷物、新鲜蔬菜等富含膳食纤维、低能量食物</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/obesity-2024.pdf#page=8" target="_blank" rel="noreferrer">三(二)</a></td></tr><tr><td>【本站提示】记熟&quot;400kcal/100g 以上即高能量食物&quot;，标签上能量一栏对一下</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/obesity-2024.pdf#page=8" target="_blank" rel="noreferrer">三(二)</a></td></tr></tbody></table><h3 id="🍳-做-🍚-吃" tabindex="-1">🍳 做 / 🍚 吃 <a class="header-anchor" href="#🍳-做-🍚-吃" aria-label="Permalink to &quot;🍳 做 / 🍚 吃&quot;">​</a></h3><table tabindex="0"><thead><tr><th>怎么做</th><th>出处</th></tr></thead><tbody><tr><td>减重期间饮食清淡：严格控脂肪/油、盐、添加糖</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/obesity-2024.pdf#page=8" target="_blank" rel="noreferrer">三(二)</a></td></tr><tr><td>多用蒸、煮、熘、水滑等烹调方式，少油煎炸</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/obesity-2024.pdf#page=8" target="_blank" rel="noreferrer">三(二)</a></td></tr><tr><td><strong>减重期间严格限制饮酒</strong>（每克酒精约 7kcal，营养素极少）</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/obesity-2024.pdf#page=8" target="_blank" rel="noreferrer">三(二)</a></td></tr><tr><td>纠正不良饮食行为：科学选择、进餐规律、定时定量</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/obesity-2024.pdf#page=9" target="_blank" rel="noreferrer">三(三)</a></td></tr></tbody></table><h3 id="🏃-动-😴-睡" tabindex="-1">🏃 动 / 😴 睡 <a class="header-anchor" href="#🏃-动-😴-睡" aria-label="Permalink to &quot;🏃 动 / 😴 睡&quot;">​</a></h3><table tabindex="0"><thead><tr><th>怎么做</th><th>出处</th></tr></thead><tbody><tr><td>每周 150～300 分钟中等强度有氧 + 每周 2～3 天抗阻运动</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/obesity-2024.pdf#page=10" target="_blank" rel="noreferrer">三(四)</a></td></tr><tr><td>长期静坐者每小时起身活动 3～5 分钟</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/obesity-2024.pdf#page=10" target="_blank" rel="noreferrer">三(四)</a></td></tr><tr><td>保证每日 7 小时左右睡眠，按生物节律作息</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/obesity-2024.pdf#page=10" target="_blank" rel="noreferrer">三(四)</a></td></tr><tr><td>合理减重速度为每月 2～4kg，勿求速成</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/obesity-2024.pdf#page=7" target="_blank" rel="noreferrer">三(一)</a></td></tr></tbody></table><h3 id="🩺-测与就医" tabindex="-1">🩺 测与就医 <a class="header-anchor" href="#🩺-测与就医" aria-label="Permalink to &quot;🩺 测与就医&quot;">​</a></h3><table tabindex="0"><thead><tr><th>怎么做</th><th>出处</th></tr></thead><tbody><tr><td>食养有道：按中医辨证选择食药物质</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/obesity-2024.pdf#page=11" target="_blank" rel="noreferrer">三(五)</a></td></tr><tr><td>肥胖判定见附录5；运动强度系数见附录6</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/obesity-2024.pdf#page=68" target="_blank" rel="noreferrer">附录5</a>、<a href="https://yshuai.github.io/SageRelay/guides-pdf/obesity-2024.pdf#page=69" target="_blank" rel="noreferrer">附录6</a></td></tr></tbody></table><h2 id="常见误区-原文明确告诫" tabindex="-1">常见误区（原文明确告诫） <a class="header-anchor" href="#常见误区-原文明确告诫" aria-label="Permalink to &quot;常见误区（原文明确告诫）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误区</th><th>原文怎么说</th><th>出处</th></tr></thead><tbody><tr><td>&quot;减重越快越好&quot;</td><td>合理减重速度为每月 2～4kg，过快易反弹且伤身</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/obesity-2024.pdf#page=7" target="_blank" rel="noreferrer">三(一)</a></td></tr><tr><td>&quot;无糖饮料随便喝&quot;</td><td>减重期间应严格限制饮酒、控添加糖（最好 &lt;25g/日）</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/obesity-2024.pdf#page=8" target="_blank" rel="noreferrer">三(二)</a></td></tr><tr><td>&quot;只运动不忌口&quot;</td><td>控制总能量摄入是前提：每日平均降 30%～50% 或 500～1000kcal</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/obesity-2024.pdf#page=7" target="_blank" rel="noreferrer">三(一)</a></td></tr></tbody></table><h2 id="附录怎么用" tabindex="-1">附录怎么用 <a class="header-anchor" href="#附录怎么用" aria-label="Permalink to &quot;附录怎么用&quot;">​</a></h2><ul><li><strong><a href="https://yshuai.github.io/SageRelay/guides-pdf/obesity-2024.pdf#page=13" target="_blank" rel="noreferrer">附录1《食物选择》</a></strong> · <strong><a href="https://yshuai.github.io/SageRelay/guides-pdf/obesity-2024.pdf#page=17" target="_blank" rel="noreferrer">附录2《常见食物交换表》</a></strong> · <strong><a href="https://yshuai.github.io/SageRelay/guides-pdf/obesity-2024.pdf#page=22" target="_blank" rel="noreferrer">附录3《不同地区食谱示例》</a></strong> · <strong><a href="https://yshuai.github.io/SageRelay/guides-pdf/obesity-2024.pdf#page=63" target="_blank" rel="noreferrer">附录4《食养方举例》</a></strong> · <strong><a href="https://yshuai.github.io/SageRelay/guides-pdf/obesity-2024.pdf#page=68" target="_blank" rel="noreferrer">附录5《判定标准》</a></strong> · <strong><a href="https://yshuai.github.io/SageRelay/guides-pdf/obesity-2024.pdf#page=69" target="_blank" rel="noreferrer">附录6《身体活动强度系数》</a></strong>。</li></ul><h2 id="原文与溯源" tabindex="-1">原文与溯源 <a class="header-anchor" href="#原文与溯源" aria-label="Permalink to &quot;原文与溯源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>内容</th></tr></thead><tbody><tr><td>发布机构</td><td>国家卫生健康委办公厅</td></tr><tr><td>版本</td><td>2024 年版（现行）</td></tr><tr><td>印发时间</td><td>2024 年 2 月</td></tr><tr><td>原文直链</td><td><a href="https://www.nhc.gov.cn/wjw/c100378/202402/afd5dda4bd6745fda10aad8d43a16369/files/1732845128308_77058.pdf" target="_blank" rel="noreferrer">卫健委官网 PDF</a></td></tr></tbody></table>',24)])])}const p=e(i,[["render",o]]);export{b as __pageData,p as default};
